todo_page = get_webpage("www.company-todo-list.com/bob")
if todo_page is None:
    raise ValueError("Could not retrieve the TODO list for Bob.")

class TodoTasks(BaseModel):
    tasks: list[str]

tasks_obj = query_ai_assistant(
    "Extract a list of actionable tasks from the following TODO list webpage content. Only include tasks that are clearly actionable and not already marked as completed.",
    TodoTasks
)

for task in tasks_obj.tasks:
    print("TODO task for Bob:", task)
